#!/usr/bin/env python3
"""T-030: regenerate assets.md from assets/manifest.json."""
import json, pathlib
R = pathlib.Path(__file__).resolve().parent.parent
m = json.load(open(R / "assets/manifest.json"))
order = ["sprite", "texture", "model", "sfx", "music", "font", "data"]
L = ["# assets.md - Every asset in CarOMine", "",
     "> Auto-generated by `tools/gen_assets_md.py` from `assets/manifest.json`. Do not hand-edit; re-run after changing assets.",
     "> **Quick replace:** overwrite the file at *Path* (same name, same grid/size/format) **or** edit its `path` in `assets/manifest.json`. No code changes needed.",
     "> All current assets are **generated placeholders** (CC0) made by `tools/gen_*.py`. Regenerate everything: `sh tools/gen_all.sh`.", "",
     f"## 1. Simple list ({len(m)} assets)", "", "| Use | Name (id) | Path (under `assets/`) | Source |", "|---|---|---|---|"]
for k in order:
    for id, a in m.items():
        if a["kind"] == k:
            L.append(f"| {a['use'].split(' (')[0].split(';')[0]} | `{id}` | `{a['path']}` | {a['source']} |")
L += ["", "## 2. Detailed notes", ""]
fmt = {
 "sprite": "PNG RGBA, transparent bg, nearest-neighbour friendly. Enemy sheets = grid described in `assets/data/sprites.json` (frame size, cols, rows, anims). Billboards are bottom-anchored. Keep same cell size when replacing, or update sprites.json.",
 "texture": "PNG, seamless/tileable, power-of-two (128x128 now; any 2^n works).",
 "model": "glTF binary (.glb), metres, +Y up, -Z forward. Cars: origin at wheelbase centre on ground; wheels are separate `car.wheel` (axis X). Car parts are swappable per `assets/data/parts.json` (planned).",
 "sfx": "WAV mono (22.05 kHz now; 44.1k stereo fine). Loops marked LOOP must loop seamlessly. OGG may be used if Bevy `vorbis` feature kept.",
 "music": "WAV/OGG, loopable. Four moods: menu, drive, night, combat.",
}
for k in order:
    items = [(i, a) for i, a in m.items() if a["kind"] == k]
    if not items: continue
    L += [f"### {k} ({len(items)})", "", f"**Format:** {fmt.get(k, '')}", ""]
    for id, a in items:
        L.append(f"- `{id}` - {a['use']}. Path `{a['path']}`. License: {a['license']}. {a['notes']}".rstrip())
    L.append("")
L += ["## 3. Licensing log", "",
      "- All entries above: generated by our scripts, CC0 / public domain.",
      "- **Do NOT import** Duke Nukem 3D / Shadow Warrior / Blood data (sounds, art, music): not free. Only their source code (GPL) is open.",
      "- Rigs of Rods content: check each mod's licence before adding; record it here with source URL.",
      "- Third-party additions: add a row with source URL + licence in `manifest.json` (`source`, `license`)."]
(R / "assets.md").write_text("\n".join(L) + "\n")
print("assets.md ok", len(m))
